import{z as i,x as A,o as r,c as p,q as s,j as E,D as l,d as o,s as n,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"窥孔与窥视窗","description":"","frontmatter":{"title":"窥孔与窥视窗","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/peephole.md","filePath":"cs/peephole.md","lastUpdated":1791063341000}'),B={name:"cs/peephole.md"};function c(h,a,m,u,f,C){const t=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=s('<h1 id="窥孔与窥视窗" tabindex="-1">窥孔与窥视窗 <a class="header-anchor" href="#窥孔与窥视窗" aria-label="Permalink to &quot;窥孔与窥视窗&quot;">​</a></h1><div class="epigraph"><p>只看相邻几条指令，用代数与控制的局部恒等替换成更短或更快的序列。</p><footer>—— 据 McKeeman, Peephole Optimization, 1965；龙书第 8 章整理</footer></div><p>上一课<a href="/cs/spill-remat">溢出与重物化</a>可能留下冗余传送、比较后多余的测试、或 spill 造成的 load-store 对。本课不重着色。缺口是：<strong>短窗口</strong>改写——窥孔——不需要全局数据流再跑一轮。窗口滑过目标指令（或 IR），模式匹配替换。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>着色与选择各自局部最优，拼接后出现 <code>move r,r</code>、<code>add x,0</code>、跳转到下一指令、<code>store</code> 立刻 <code>load</code> 同地址。全局 CSE 可能已做过，但寄存器分配之后新的垃圾才出现。缺口是分配后的本地清理，不是再插 φ。</p><p>窗口长度常数，故线性一遍或直到无匹配。不保证全局最优；正确性靠每条规则的语义等价（含标志位）。</p><h3 id="窥孔不是数据流" tabindex="-1">窥孔不是数据流 <a class="header-anchor" href="#窥孔不是数据流" aria-label="Permalink to &quot;窥孔不是数据流&quot;">​</a></h3><p>活跃分析看全 CFG。窥孔不求解方程，只认有限模式。有的规则需要「下一指令不是标号目标」之类的局部控制知识，仍不是不动点框架。</p><p><span class="marginnote">McKeeman 1965 命名 peephole。龙书把窥孔放在代码生成之后。本课规则举类不列工业目录。GCC/LLVM 的 InstCombine 是 IR 层同类物。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>维护长度为 \\(w\\) 的缓冲。规则：恒等运算删除、强度削弱（移位代乘常数，仅当 ISA 有且语义同）、跳转链压缩、死传送。替换后回退窗口以免错过重叠。</p>',11)),(r(),E(d,null,{default:l(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MI%5B%22%E6%9C%BA%E5%99%A8%E6%8C%87%E4%BB%A4%E5%BA%8F%E5%88%97%22%5D%20--%3E%20WIN%5B%22%E9%95%BF%E5%BA%A6%20w%20%E7%9A%84%E7%AA%97%E5%8F%A3%22%5D%0A%20%20WIN%20--%3E%20RUL%5B%22%E6%A8%A1%E5%BC%8F%E6%9B%BF%E6%8D%A2%22%5D%0A%20%20RUL%20--%3E%20MI%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/riscv-int-isa"},"RISC-V"),o(" 上立即数 0、伪指令展开后再窥孔，避免对伪指令与真指令各写一套还不一致。窗口不要跨基本块边界，除非能证明中间没有入口。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},[o("数字实例（强度削弱）：把 \\(x\\) 乘以 8 写成 "),e("code",null,"x << 3"),o("——8 就是 \\(2^3\\)，左移 3 位在二进制里恰好等于乘 8。很多处理器上乘法指令要 3 个周期以上，移位只要 1 个；但规则只在乘数恰好是 2 的幂时成立，乘以 7 就老老实实用乘法。")])],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"与流水线：窥孔可消掉无用比较，减少控制冒险来源，但不代替分支预测。与 ABI：不要删掉为遵守调用约定而存在的保存/恢复，除非能证多余——那通常要活跃，超出纯窥孔。安全做法：窥孔不做跨调用的删保存。",-1)),(r(),E(d,null,{default:l(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20BEFORE%5B%22%E7%AA%97%E5%8F%A3%E5%86%85%EF%BC%9A%E6%94%B9%E5%86%99%E5%89%8D%22%5D%0A%20%20%20%20A1%5B%22mov%20r2%2C%20r2%22%5D%20--%3E%20A2%5B%22add%20r2%2C%200%22%5D%20--%3E%20A3%5B%22jmp%20%E4%B8%8B%E4%B8%80%E8%A1%8C%22%5D%0A%20%20end%0A%20%20subgraph%20RULE%5B%22%E5%8C%B9%E9%85%8D%E5%88%B0%E7%9A%84%E8%A7%84%E5%88%99%22%5D%0A%20%20%20%20R1%5B%22%E8%87%AA%E5%A4%8D%E5%88%B6%20%E2%86%92%20%E5%88%A0%E9%99%A4%22%5D%0A%20%20%20%20R2%5B%22%E5%8A%A0%200%20%E2%86%92%20%E5%88%A0%E9%99%A4%22%5D%0A%20%20%20%20R3%5B%22%E8%B7%B3%E5%88%B0%E4%B8%8B%E4%B8%80%E6%8C%87%E4%BB%A4%20%E2%86%92%20%E5%88%A0%E9%99%A4%22%5D%0A%20%20end%0A%20%20subgraph%20AFTER%5B%22%E6%94%B9%E5%86%99%E5%90%8E%22%5D%0A%20%20%20%20B1%5B%22%EF%BC%88%E7%A9%BA%EF%BC%9A%E7%AA%97%E5%8F%A3%E5%86%85%E6%8C%87%E4%BB%A4%E5%85%A8%E6%B6%88%EF%BC%89%22%5D%0A%20%20end%0A%20%20BEFORE%20--%3E%20RULE%20--%3E%20AFTER%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>这张图回答的问题是：窥孔「匹配并替换」具体长什么样？窗口里连续三条指令各自命中一条恒等规则：复制给自己、加零、跳到紧邻的下一行——它们对程序行为没有任何影响，逐条删掉即可。每一步替换都语义等价（连标志位也不动），所以不需要任何全局分析就敢下手；替换后窗口回退重扫，防止新暴露的相邻指令还能继续消。</p><p><span class="marginnote">直觉类比：窥孔像校对员拿着一张只盖得住三行的纸片读稿——看不见全文结构，只修纸片里的错别字和重复用词。修不了「第三章与第七章自相矛盾」这种全局问题，但胜在快：一遍扫完、绝不误伤，改的每处都确定是对的。</span></p><p>替换可能缩短窗口，应再扫一遍直到稳定，但仍保持局部。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写链接器、不排指令调度算法（list scheduling）。不改 ABI。后课默认：函数已是可按约定发射的指令。下一课把物理寄存器与栈帧钉成对其他编译单元也成立的二进制接口。</p><p><span class="marginnote">常见误区：以为窥孔能替代数据流优化——「反正都能删冗余代码」。窥孔只认有限模式，<code>x*8</code> 写成移位它认得，<code>x*8 - x*4</code> 等于 <code>x*4</code> 这种要跨语句做代数推理的它认不得；后者需要全局数据流。两者是分工关系：数据流先把冗余大体清干净，窥孔在寄存器分配后再做最后一道精细抛光。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窥孔 = 常数窗口上的语义等价改写。</li><li>分配之后尤其需要；线性、不全局最优。</li><li>不擅自删调用保存；窗口默认不跨块。</li><li>出处：McKeeman, 1965；Aho et al., 龙书第 8 章。</li></ul>',8))])}const b=i(B,[["render",c]]);export{_ as __pageData,b as default};
